pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        // keep the fuzz params in a wide but admissible domain
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);

        // give C a working LogFile (admissible environment: SetLogFile succeeds before Initialized())
        LogHelper log = new LogHelper();
        c.SetLogFile(address(log));

        // any admissible depositor can deposit successfully when Log is properly set
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

// minimal LogFile stand-in so the reference's Log.AddMessage call succeeds
contract LogHelper {
    function AddMessage(address, uint, string calldata) external pure {}
}

